function erzeugeBonbon(binderId, zutatIds) {
  const binder = BINDER[binderId];
  const [h1] = FARBEN[zutatIds[0]] || ['#c9a86c'];
  const [h2] = FARBEN[zutatIds[1]] || ['#a86cc9'];
  const gid = 'bonbon-' + Math.random().toString(36).slice(2, 8);
  const grad = `<linearGradient id="${gid}" x1="0" y1="0" x2="1" y2="1">` +
    `<stop offset="0%" stop-color="${h1}"/><stop offset="100%" stop-color="${h2}"/></linearGradient>`;
  // Form nach dem Binder; Farben immer aus den beiden Zutaten.
  const form = binder.effekt === 'daempft_klang' ? BONBON_FORMEN.tropfen
             : binder.effekt === 'kuehlt_ab'     ? BONBON_FORMEN.kristall
             :                                     BONBON_FORMEN.rund;
  const inner = form.inner
    .map((d) => `<path d="${d}" fill="#fff" fill-opacity=".3"/>`).join('');
  const markup = `<g class="bonbon-figur"><defs>${grad}</defs>` +
    `<g transform="${form.norm}">` +
    `<path d="${form.body}" fill="url(#${gid})" stroke="#2c1c10" ` +
    `stroke-width="${form.sw}" stroke-linejoin="round"/>${inner}</g></g>`;
  return { markup, h1, h2 };
}

// Das aktuelle Bonbon wird einmal erzeugt und gemerkt — so trägt der Sud im
// Topf dieselben Farben/Textur wie das Bonbon, das später herauskommt.
// Wird zurückgesetzt, sobald sich der Schüsselinhalt ändert.
function getBonbon() {
  if (!state.bonbon) {
    state.bonbon = erzeugeBonbon(state.schale.binder, state.schale.zutat);
  }
  return state.bonbon;
}

// Sud-Textur im Topf: Farbverlauf des Bonbons (dieselben Zutatenfarben),
// als Ellipse im Topf-Koordinatensystem (cx80 cy68).
function topfTextur() {
  const b = getBonbon();
  const gid = 'topf-' + Math.random().toString(36).slice(2, 7);
  return `<defs>
      <linearGradient id="${gid}" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="${b.h1}"/>
        <stop offset="100%" stop-color="${b.h2}"/>
      </linearGradient>
    </defs>
    <ellipse cx="80" cy="68" rx="36" ry="8" fill="url(#${gid})"/>`;
}

// --- Maus, zwei Posen -------------------------------------
function bluete(x, y, r, farbe, mitte = '#f7e7b0') {
  let p = '';
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 - Math.PI / 2;
    const px = (x + Math.cos(a) * r * 0.66).toFixed(1);
    const py = (y + Math.sin(a) * r * 0.66).toFixed(1);
    const dreh = (a * 180 / Math.PI + 90).toFixed(1);
    p += `<ellipse cx="${px}" cy="${py}" rx="${(r * 0.62).toFixed(1)}" ry="${(r * 0.48).toFixed(1)}" ` +
         `transform="rotate(${dreh} ${px} ${py})" fill="${farbe}"/>`;
  }
  return p + `<circle cx="${x}" cy="${y}" r="${(r * 0.3).toFixed(1)}" fill="${mitte}"/>`;
}

